        "requirement_id": "REQ-001",
        "title": "Teen-Friendly Site Design",
        "description": "Maintaining a teen friendly site is deemed of highest importance in order to hold student attention and guide the viewer to information that will lead to a decision to pursue a career in CS.",
        "type": "non-functional",
        "acceptance_criteria": ["Site appeals to teen demographic based on usability testing"],
        "source_location": {
