            "verse": ["Maintaining a teen friendly site is deemed of highest importance in order to hold student attention and guide the viewer to information that will lead to a decision to pursue a career in CS."]
        }
    },
    {
        "requirement_id": "REQ-002",
        "title": "Browser Compatibility",
        "description": "The Get Real site should work and be tested against IE, Firefox and Netscape.",
        "type": "non-functional",
        "acceptance_criteria": ["Site renders correctly in IE, Firefox, and Netscape"],
        "source_location": {
            "document": "get-real-0.2",
            "verse": ["The Get Real site should work and be tested against IE, Firefox and Netscape."]
        }
    },
    {
        "requirement_id": "REQ-003",
        "title": "Internal and External Search",
        "description": "The system shall provide two kinds of searches: internal search of the Get Real site, and external search of CS related outside sites such as OUS campuses and articles on CS.",
        "type": "functional",
        "acceptance_criteria": ["Internal search returns results from Get Real site", "External search returns results from OUS campuses and CS articles"],
        "source_location": {
            "document": "get-real-0.2",
            "verse": ["At least two kinds of searches are needed, 1) internal search of the Get Real site, and 2) external search of CS related outside sites such as OUS campuses, articles on CS etc."]
        }
    },
    {
        "requirement_id": "REQ-004",
        "title": "Q&A Feedback System",
        "description": "The system shall provide a Q and A format for students to ask questions to the Oregon University System, with answers posted in an FAQ section.",
        "type": "functional",
        "acceptance_criteria": ["Users can submit questions in Q&A format", "Answers are posted in a publicly visible FAQ section"],
        "source_location": {
            "document": "get-real-0.2",
            "verse": ["Get fast feedback from the Oregon University System on questions asked in a Q and A format. Answers are posted in an FAQ section for all to read."]
        }
    },
    {
        "requirement_id": "REQ-005",
        "title": "Usage Analytics",
        "description": "The system shall track and evaluate hits and time spent on the student-focused website over time.",
        "type": "functional",
        "acceptance_criteria": ["Hit counters are tracked", "Average time-on-page metrics are available", "Administrators can view analytics reports"],
        "source_location": {
            "document": "get-real-0.2",
            "verse": ["There is a need to track and evaluate the \"hits\" and time spent on the student-focused website over time; and make content, design, and navigation changes as needed based on evaluation of hits."]
        }
    }
]

