[
    {
        "requirement_id": "REQ-001",
        "title": "Site Benefits Information",
        "description": "The system shall provide personal and career information from CS professionals, CS course information from OUS campuses, timely updates, and plans for students to prepare for a CS career.",
        "type": "functional",
        "acceptance_criteria": ["Site displays career information from CS professionals", "Links to OUS campus CS course information exist", "Content is regularly updated"],
        "source_location": {
            "document": "get-real-0.2",
            "verse": ["Benefits for using the site should include: Personal and Career information from a broad spectrum of CS professionals, CS course and other information from OUS campuses, Timely and up to date information that encourages readers to return to the site, may include Q & A, Call to action, and plans for students to follow to prepare for a CS career"]
        }
    },
    {
        "requirement_id": "REQ-002",
        "title": "Target Audience Coverage",
        "description": "The site shall serve two audiences: (1) students interested in CS seeking in-depth career information, and (2) college-bound students who might be attracted to CS with the right information.",
        "type": "non-functional",
        "acceptance_criteria": ["Site content addresses both target audience groups"],
        "source_location": {
            "document": "get-real-0.2",
            "verse": ["Two potential groups of viewers (students) exist: 1) students interested in CS seeking more in-depth information about a CS career, and 2) college bound students not necessarily interested in CS who might be attracted to a CS career with the right \"push\" from information on the Get Real site."]
        }
    },
    {
        "requirement_id": "REQ-003",
        "title": "OUS Domain Integration",
        "description": "The site shall run as an extension of the OUS domain to maximize search engine visibility, hosted on OSU servers.",
        "type": "non-functional",
        "acceptance_criteria": ["Site is hosted on OSU servers under the OUS domain"],
        "source_location": {
            "document": "get-real-0.2",
            "verse": ["The Get Real site runs as an extension of the OUS site e.g. ~getreal.ous.edu~ Being part of the OUS domain will maximize Google and other search engine hits. The site runs on OSU servers."]
        }
    }
]

